        "Use roles to group your server members and assign permissions.": "استخدم الرتب لتجميع أعضاء السيرفر الخاص بك وتعيين الأذونات.",
        "Roles – 1": "الرتب – 1",
        "Default permissions for all server members": "الأذونات الافتراضية لجميع أعضاء السيرفر",
