        "Start with one of our templates": "ابدأ بأحد قوالبنا",
        "Push to Talk (Priority)": "اضغط لتتحدث (الأولوية)",
        "Allows members to be more easily heard in voice channels. When activated, the volume of others without this permission will be automatically lowered. Priority Speaker is activated by using the": "يسمح للأعضاء بالاستماع بسهولة أكبر في الرومات الصوتية. عند التنشيط، سيتم خفض مستوى الصوت للآخرين دون هذا الإذن تلقائيًا. يتم تنشيط مكبر الصوت ذو الأولوية باستخدام",
        "keybind.": "com.keybind.",
        "Allows members to send sounds from server soundboard.": "يسمح للأعضاء بإرسال الأصوات من بموجه الصوت للسيرفر.",
        "View Channels": "عرض الرومات",
