        "Assign this role to your members. Members can have more than one role. You can add up to 30 at a time.": "قم بتعيين هذا الرتبة لأعضائك. يمكن أن يكون للأعضاء أكثر من رتبة واحد. يمكنك إضافة ما يصل إلى 30 في المرة الواحدة.",
        "Finish": "إنهاء",
        "Search members": "أعضاء البحث",
        "Create Linked Role": "إنشاء رتبة مرتبط",
        "Linking a connection or app requires members to connect their accounts before being added to the role.": "يتطلب ربط اتصال أو تطبيق من الأعضاء ربط حساباتهم قبل إضافتهم إلى الرتبة.",
        "Learn more about Linked Roles": "تعرف على المزيد حول الرتب المرتبطة",
