        "magical": "سحري",
        "Make certain roles": "القيام برتب معينة",
        "Unlock new role styles with Boosting.": "افتح أنماط الرتب الجديدة من خلال التعزيز.",
        "Invite links, embeds, and vanity urls will still be visible, but new users will no longer be able to join this server.": "ستظل روابط الدعوة والتضمينات وعناوين URL المخصصة مرئية، ولكن لن يتمكن المستخدمون الجدد من الانضمام إلى هذا السيرفر.",
        "Revoke": "إبطال",
        "Expires in:": "تنتهي صلاحيته في:",
        "Members of the server must meet the following criteria before they can send messages in text channels or initiate a\ndirect message conversation. If a member has an assigned role and server onboarding is not enabled, this does not apply.": "يجب أن يستوفي أعضاء السيرفر المعايير التالية قبل أن يتمكنوا من إرسال الرسائل في الرومات النصية أو بدء عملية\nمحادثة الرسائل المباشرة. إذا كان للعضو رتبة معين ولم يتم تمكين إعداد السيرفر، فلن ينطبق هذا.",
        "We recommend setting a verification level for a Community Server.": "نوصي بتعيين مستوى التحقق لسيرفر المجتمع.",
        "Unrestricted": "غير مقيد",
        "Low": "منخفض",
        "Must have a verified email on their Discord account.": "يجب أن يكون لديه بريد إلكتروني تم التحقق منه على حساب Discord الخاص به.",
        "Medium": "متوسط",
        "Must also be registered on Discord for longer than 5 minutes.": "يجب أيضًا التسجيل على Discord لمدة تزيد عن 5 دقائق.",
        "High": "عالية",
        "Must also be a member of this server for longer than 10 minutes.": "يجب أيضًا أن تكون عضوًا في هذا السيرفر لمدة تزيد عن 10 دقائق.",
        "Highest": "الأعلى",
        "Must have a verified phone on their Discord account.": "يجب أن يكون لديك هاتف تم التحقق منه على حساب Discord الخاص بهم.",
        "Choose if server members can share image-based media detected by Discord’s sensitive content filters. This setting will apply to channels that are not age-restricted.": "اختر ما إذا كان بإمكان أعضاء السيرفر مشاركة الوسائط المستندة إلى الصور التي اكتشفتها مرشحات المحتوى الحساس في Discord. سينطبق هذا الإعداد على الرومات غير المقيدة بالفئة العمرية.",
        "Filter messages from all members": "تصفية الرسائل من كافة الأعضاء",
        "All messages will be filtered for sensitive image-based media.": "سيتم تصفية كافة الرسائل للوسائط الحساسة القائمة على الصور.",
        "Filter messages from server members without roles": "تصفية الرسائل من أعضاء السيرفر بدون رتب",
        "Messages from server members without a role will be filtered for sensitive image-based media.": "سيتم تصفية الرسائل الواردة من أعضاء السيرفر الذين ليس لديهم رتبة للوسائط الحساسة المستندة إلى الصور.",
        "Do not filter": "لا تصفية",
