        "Find Friends": "البحث عن الأصدقاء",
        "Add me as a friend on Discord! Invite expires in 1 week: https://discord.gg/abKenJAp": "أضفني كصديق على الديسكورد! تنتهي صلاحية الدعوة خلال أسبوع واحد: https://discord.gg/abKenJAp",
