        "Show images, videos, and lolcats...": "عرض الصور ومقاطع الفيديو والقطط...",
        "Image descriptions are used to describe images for screen readers.": "تُستخدم أوصاف الصور لوصف الصور لقارئات الشاشة.",
        "Camera Uploads": "تحميلات الكاميرا",
        "When this is on, images and videos captured using the camera when sending a message will save to the device as well": "عند تشغيل هذا الخيار، سيتم حفظ الصور ومقاطع الفيديو التي تم التقاطها باستخدام الكاميرا عند إرسال رسالة على الجهاز أيضًا",
        "Data Consumption": "استهلاك البيانات",
        "When this is on, images and videos will be sent in lower quality on cellular networks to reduce data usage.": "عند تشغيل هذا الخيار، سيتم إرسال الصور ومقاطع الفيديو بجودة أقل على الشبكات الخلوية لتقليل استخدام البيانات.",
        "Embeds and Link Previews": "التضمين ومعاينات الارتباط",
        "Allows stickers to appear in your autocomplete results.": "يسمح للملصقات بالظهور في نتائج الإكمال التلقائي.",
        "Gestures": "الإيماءات",
        "Sync": "مزامنة",
        "Turning this on will overwrite text & image settings on all other clients including desktop and browser.": "سيؤدي تشغيل هذا إلى استبدال إعدادات النص والصور على جميع العملاء الآخرين بما في ذلك سطح المكتب والمتصفح.",
        "Best Quality": "أفضل جودة",
        "Standard (recommended)": "قياسي (مستحسن)",
        "Best Quality will use more data. Data Saver will upload faster and use less cellular data.": "ستستخدم أفضل جودة المزيد من البيانات. سيتم تحميل موفر البيانات بشكل أسرع واستخدام بيانات خلوية أقل.",
        "Unlock 1080p video uploads with Nitro": "قم بفتح تحميلات الفيديو بدقة 1080 بكسل باستخدام Nitro",
        "For example, when you type :) Discord will convert it to 🙂": "على سبيل المثال، عندما تكتب :) Discord سوف يحولها إلى 🙂",
        "On click": "عند النقر",
