        "On servers I moderate": "على السيرفرات أنا معتدلة",
        "Show Channel Details": "عرض تفاصيل الروم",
        "Search, members, media, pins, threads, and more": "البحث والأعضاء والوسائط والدبابيس والمواضيع والمزيد",
        "Reply to Message": "الرد على الرسالة",
