        "Learn more about": "تعلم المزيد عن",
        "role colors and other accessibility settings": "ألوان الرتب وإعدادات إمكانية الوصول الأخرى",
        "Choose how official developer messages look on verified servers that support it.": "اختر كيفية ظهور رسائل المطورين الرسمية على السيرفرات التي تم التحقق منها والتي تدعمها.",
        "display name styles": "أنماط اسم العرض",
        ", including font, effect, and color across Discord.": "، بما في ذلك الخط والتأثير واللون عبر Discord.",
        "Adjust the contrast between foreground and background colors": "ضبط التباين بين الألوان الأمامية والخلفية",
        "Reduce the saturation of colors within the application, for those with color sensitivities. This does not affect the saturation of images, videos, role colors or other user-provided content by default.": "تقليل تشبع الألوان داخل التطبيق، لمن يعانون من حساسية الألوان. ولا يؤثر هذا على تشبع الصور أو مقاطع الفيديو أو ألوان الرتب أو أي محتوى آخر يقدمه المستخدم بشكل افتراضي.",
        "Keep pop-up notifications on screen for at least this long. Notifications that already stay longer are unaffected.": "احتفظ بالإشعارات المنبثقة على الشاشة لمدة طويلة على الأقل. ولا تتأثر الإشعارات التي تبقى لفترة أطول بالفعل.",
        "Make links to websites, help articles, and other pages stand out more by underlining them.": "اجعل الروابط إلى مواقع الويب ومقالات المساعدة والصفحات الأخرى أكثر وضوحًا من خلال وضع خط تحتها.",
        "On forms, menus and settings, on/off toggles will have icons.": "في النماذج والقوائم والإعدادات، ستحتوي مفاتيح التشغيل/الإيقاف على أيقونات.",
        "Profile Colors": "ألوان الملف الشخصي",
