        "theme": "theme",
        "Reduce the amount and intensity of animations, hover effects, and other moving effects across Discord. Need help? Check our": "قم بتقليل كمية وكثافة الرسوم المتحركة وتأثيرات التمرير والتأثيرات المتحركة الأخرى عبر Discord. بحاجة الى مساعدة؟ تحقق لدينا",
