        "Who would you like to add as a friend?": "من تريد إضافته كصديق؟",
        "Username#0000": "اسم المستخدم#0000",
        "Personalize your request (Optional)": "تخصيص طلبك (اختياري)",
        "What you write here will also show up in your DM if you become friends.": "ما تكتبه هنا سيظهر أيضًا في رسالتك المباشرة إذا أصبحت صديقًا.",
        "Enter a username": "أدخل اسم المستخدم",
        "Character count, 120 characters remaining": "عدد الأحرف، 120 حرفًا متبقيًا",
        "Slash command application Carl-bot": "تطبيق أمر القطع المائل Carl-bot",
        "Slash about. Shows some interesting stats about the bot. From Carl-bot": "قطع حول. يعرض بعض الإحصائيات المثيرة للاهتمام حول الروبوت. من كارل بوت",
        "Slash automod attachmentspam disable. Disable Attachmentspam. From Carl-bot": "تعطيل المرفقات التلقائية المائلة غير المرغوب فيها. تعطيل المرفقات غير المرغوب فيها. من كارل بوت",
        "Slash automod attachmentspam punishment. Sets the punishment(s) for hitting the rate limit.. From Carl-bot": "خفض المرفقات التلقائية عقوبة البريد العشوائي. يحدد العقوبة (العقوبات) لبلوغ الحد الأقصى للمعدل.. من Carl-bot",
        "Slash automod attachmentspam set. Set attachment settings for the server. From Carl-bot": "قطع مجموعة المرفقات التلقائية غير المرغوب فيها. ضبط إعدادات المرفقات للسيرفر. من كارل بوت",
        "Slash automod caps limit. Set caps limit for the server. From Carl-bot": "خفض الحد الأقصى لأغطية السيارات. تعيين الحد الأقصى للسيرفر. من كارل بوت",
        "Slash automod caps punishment. Sets the punishment(s) for hitting the rate limit.. From Carl-bot": "خفض قبعات automod العقاب. يحدد العقوبة (العقوبات) لبلوغ الحد الأقصى للمعدل.. من Carl-bot",
        "Slash automod censor clear. Removes all blacklisted words. From Carl-bot": "خفض رقابة automod واضحة. يزيل جميع الكلمات المدرجة في القائمة السوداء. من كارل بوت",
        "Slash automod censor display. Shows all the blacklisted words. From Carl-bot": "خفض عرض الرقابة التلقائية. يظهر جميع الكلمات المدرجة في القائمة السوداء. من كارل بوت",
        "Slash automod censor punishment. Sets the punishment(s) for saying a bad word.. From Carl-bot": "خفض عقوبة رقابة السيارات. يحدد العقوبة (العقوبات) لقول كلمة سيئة.. من كارل بوت",
        "Application commands list opened": "تم فتح قائمة أوامر التطبيق",
        "Carl-bot application selected": "تم تحديد تطبيق Carl-bot",
        "Dyno application": "تطبيق داينو",
        "Emoji.gg application": "تطبيق Emoji.gg",
        "InviteLogger application": "تطبيق إنفيتلوجر",
        "Make it a Quote application": "جعله تطبيق الاقتباس",
        "ProBot ✨ application": "تطبيق ProBot ✨",
        "Quark application": "تطبيق كوارك",
        "Quran Radio application": "تطبيق إذاعة القرآن الكريم",
        "Role Keeper application": "تطبيق حارس الرتبة",
        "Security application": "تطبيق الأمن",
        "Statbot application": "تطبيق ستاتبوت",
        "Ticket King application": "تطبيق تذكرة الملك",
        "Ticket Tool application": "تطبيق أداة التذاكر",
        "Top.gg application": "تطبيق Top.gg",
        "Wicks application": "تطبيق الفتائل",
        "Wordle application": "تطبيق وورد",
        "Slash automod censor server. View censor settings for server. From Carl-bot": "خفض سيرفر الرقابة التلقائي. عرض إعدادات الرقابة على السيرفر. من كارل بوت",
        "Slash automod censor words. Removes/Adds one or more words from the blacklist. From Carl-bot": "خفض الكلمات الرقابية التلقائية. إزالة/إضافة كلمة واحدة أو أكثر من القائمة السوداء. من كارل بوت",
        "Slash automod deletefiles. Deletes posted Non-image/video/text files from server. From Carl-bot": "خفض الملفات تلقائيا. يحذف الملفات غير الصورية/الفيديو/النصية المنشورة من السيرفر. من كارل بوت",
        "Slash automod drama. Set up a drama channel for mods only. This channel should not be made public.. From Carl-bot": "دراما السيارات المائلة. أنشئ روم دراما للمودلات فقط. لا ينبغي أن تكون هذه الروم علنية.. من كارل بوت",
        "Slash automod honeypot add. Add honeypot channels. From Carl-bot": "أضف مصيدة القطع التلقائية. إضافة رومات العسل. من كارل بوت",
        "Slash automod honeypot clear. Clear all honeypot settings. From Carl-bot": "خفض مصيدة automod واضحة. مسح جميع إعدادات مصيدة الجذب. من كارل بوت",
        "Slash automod honeypot punishment. Sets punishment(s) for honeypot trigger. From Carl-bot": "خفض عقوبة مصيدة الجذب التلقائية. يحدد العقوبة (العقوبات) لمشغل مصيدة الجذب. من كارل بوت",
        "Slash automod honeypot remove. Remove honeypot channels. From Carl-bot": "قم بإزالة مصيدة القطع التلقائية. إزالة الرومات المصيدة. من كارل بوت",
        "Slash automod honeypot server. Shows honeypot settings for this server. From Carl-bot": "خفض سيرفر مصيدة الجذب التلقائي. يظهر إعدادات مصيدة الجذب لهذا السيرفر. من كارل بوت",
        "Slash automod invitespam norole. Same as setting it to 'block' except it only affects members without roles.. From Carl-bot": "خفض تلقائي لدعوة البريد العشوائي نورول. مثل تعيينه على \"حظر\" إلا أنه يؤثر فقط على الأعضاء الذين ليس لديهم رتب.. من Carl-bot",
        "Slash automod invitespam punishment. Sets the punishment(s) for posting server invites.. From Carl-bot": "خفض تلقائي يدعو عقوبة البريد العشوائي. يحدد العقوبة (العقوبات) لنشر دعوات السيرفر.. من Carl-bot",
        "Slash automod invitespam server. Shows Invitespam settings for this server. From Carl-bot": "خفض تلقائي لسيرفر الدعوة غير المرغوب فيها. يعرض إعدادات Invitespam لهذا السيرفر. من كارل بوت",
        "Slash automod linkspam blacklist. Blocks/Unblocks links on a domain level. From Carl-bot": "خفض القائمة السوداء لروابط البريد العشوائي التلقائية. حظر/إلغاء حظر الروابط على مستوى المجال. من كارل بوت",
