        "This will determine whether members who have not explicitly set their notification settings receive a notification for every message sent in this server or not. We highly recommend setting this to only @mentions for a Community Server.": "سيحدد هذا ما إذا كان الأعضاء الذين لم يقوموا بتعيين إعدادات الإشعارات الخاصة بهم بشكل صريح سيتلقون إشعارًا لكل رسالة يتم إرسالها في هذا السيرفر أم لا. نوصي بشدة بتعيين هذا على @الإشارات فقط لسيرفر المجتمع.",
        "Due to this server's size, members will not get mobile push notifications for non-@mention messages.": "نظرًا لحجم هذا السيرفر، لن يحصل الأعضاء على إشعارات الدفع عبر الهاتف المحمول للرسائل التي لا تتضمن @الإشارة.",
