        if (Object.prototype.hasOwnProperty.call(AR_STRINGS, core)) return leading + AR_STRINGS[core] + trailing;
        if (Object.prototype.hasOwnProperty.call(cfg.arCache, core)) return leading + cfg.arCache[core] + trailing;
        enqueueTranslation(core);
